from pathlib import Path

ANCHOR = "https://github.com/AminMortezaie/relocation-jobs/blob/main/docs/contributing.md"

def strip_one(text: str) -> str:
    i = text.find(ANCHOR)
    if i < 0:
        return text
    li = text.rfind("<li>", i - 40, i)
    if li >= 0 and text.startswith('<li><a href="', li):
        end = text.find("</li>", i) + len("</li>")
        return text[:li] + text[end:]
    key = text.rfind("Contributing", i - 90, i)
    bracket = text.rfind("[", key - 24, key)
    start = text.rfind(",", 0, bracket)
    end_label = text.find("Contributing", i + len(ANCHOR))
    end = text.find("}]}]", end_label)
    if min(start, bracket, end_label, end) < 0:
        raise SystemExit(f"{start} {bracket} {end_label} {end}")
    end += 4
    removed = text[start:end]
    if ANCHOR not in removed or "Source" in removed or "Engineering" in removed:
        raise SystemExit(removed[:300])
    return text[:start] + text[end:]

root = Path("relocation_jobs/static/homepage")
updated = 0
for path in root.rglob("*"):
    if not path.is_file():
        continue
    try:
        text = path.read_text(encoding="utf-8")
    except UnicodeDecodeError:
        continue
    if ANCHOR not in text:
        continue
    new = text
    while ANCHOR in new:
        new = strip_one(new)
    path.write_text(new, encoding="utf-8")
    updated += 1
print("updated", updated)
